"""Rebuild the three mobility project pages and integrate existing topic galleries."""
import html
import json
import re
import zipfile
from pathlib import Path

ROOT=Path(__file__).resolve().parent
TOPIC='ml-ai-mobility'
def esc(s):return html.escape(str(s),quote=True)
def bi(tag,pt,en,attrs=''):return f'<{tag} {attrs} data-pt="{esc(pt)}" data-en="{esc(en)}">{esc(pt)}</{tag}>'
def option(value,pt,en):return bi('option',pt,en,f'value="{value}"')
def label(id,pt,en,control):return f'<label for="{id}">{bi("span",pt,en)}{control}</label>'

