def controls(p):
    if p['kind']=='gps':
        fields=label('algorithm','Algoritmo','Algorithm','<select id="algorithm"><option value="astar">A*</option><option value="dijkstra">Dijkstra</option></select>')
        fields+=label('congestion','Trânsito no corredor','Corridor traffic','<select id="congestion">'+''.join(option(v,pt,en) for v,pt,en in [('1','Livre · 1×','Free · 1×'),('2.5','Moderado · 2,5×','Moderate · 2.5×'),('5','Intenso · 5×','Heavy · 5×')])+'</select>')
        for id,pt,en,default in [('origin','Origem','Origin',21),('destination','Destino','Destination',27)]:fields+=label(id,pt,en,f'<select id="{id}">'+''.join(f'<option value="{i}" {"selected" if i==default else ""}>{i}</option>' for i in range(49))+'</select>')
        fields+=label('noise','Ruído GPS (m)','GPS noise (m)','<select id="noise"><option>15</option><option selected>60</option><option>140</option></select>')
        fields+=label('closure','Bloquear trecho 23–24','Close road 23–24','<input id="closure" type="checkbox">')
    elif p['kind']=='cars':
        fields=label('cars','Quantidade de carros','Number of cars','<select id="cars"><option>12</option><option selected>32</option><option>64</option></select>')
        fields+=label('speed','Velocidade desejada (km/h)','Desired speed (km/h)','<select id="speed"><option>40</option><option selected>80</option><option>110</option></select>')
        fields+=label('brake','Frenagem no segundo 40','Braking at second 40','<input id="brake" type="checkbox" checked>')
    else:
        fields=label('city','Cenário urbano','Urban scenario','<select id="city">'+''.join(option(*a) for a in [('compact','Compacta','Compact'),('commuter','Pendular','Commuter'),('distributed','Distribuída','Distributed')])+'</select>')
        fields+=label('fleet','Tamanho da frota','Fleet size','<select id="fleet"><option>8</option><option selected>16</option><option>24</option></select>')
        fields+=label('policy','Política operacional','Operating policy','<select id="policy">'+''.join(option(*a) for a in [('random','Despacho aleatório','Random dispatch'),('nearest','Veículo mais próximo','Nearest vehicle'),('qlearning','Q-learning · reposicionar','Q-learning · reposition')])+'</select>')
    return '<div class="mobility-controls">'+fields+bi('button','Executar cenário','Run scenario','id="run" type="button"')+'</div>'

def page(p):
    slug=p['slug'];kind=p['kind']
    evidence=''.join('<div><strong>'+a+'</strong>'+bi('span',b,c)+'</div>' for a,b,c in p['metrics'])
    summary=''.join('<div class="summary-item">'+bi('h3',*h)+bi('p',*p[k])+'</div>' for k,h in [('goal',('Objetivo e valor','Goal and value')),('implementation',('Como funciona','How it works')),('validation',('Experimentos e validação','Experiments and validation')),('limits',('Limites atuais','Current limitations'))])
    playback='' if kind=='gps' else '<div class="mobility-controls">'+bi('button','Reproduzir','Play','id="play" type="button"')+'</div>'+label('timeline','Instante da reprodução','Playback time','<input class="mobility-progress" id="timeline" type="range" min="0" max="119" value="0">')
    extra=''
    if kind=='fleet':
        extra='<section class="project-panel">'+bi('h2','Compare estratégias','Compare strategies')+bi('p','Mesma demanda por seed para todas as políticas. Q-learning usa treino separado; não há garantia de superioridade.','Same demand per seed across policies. Q-learning uses separate training; superiority is not guaranteed.')+'<div id="comparisons" class="mobility-experiments"></div><p id="forecast"></p></section><section class="project-panel">'+bi('h2','Compare com contagens observadas','Compare against observed counts')+bi('p','CSV com colunas minute,observed,simulated e um intervalo único por linha. Mesmas unidades e janelas temporais devem ser garantidas por você. O arquivo não sai do navegador.','CSV with minute,observed,simulated columns and one unique interval per row. Ensure matching units and time windows. The file stays in your browser.')+label('counts','Selecionar CSV (até 2 MB)','Select CSV (up to 2 MB)','<input id="counts" type="file" accept=".csv,text/csv">')+'<p id="csv-result" aria-live="polite"></p><pre><code>minute,observed,simulated\n0,10,12\n1,4,2</code></pre>'+bi('p','O exemplo é sintético. Inserir um CSV não confirma a origem dos dados nem calibra o simulador automaticamente.','The example is synthetic. Importing a CSV does not verify data provenance or automatically calibrate the simulator.')+'</section>'
    if kind=='fleet':
        extra+='<section class="project-panel">'+bi('h2','Dataset sintético para experimentar','Synthetic dataset to experiment with')+bi('p','Pedidos do cenário pendular, seed 7. Colunas: id, minute, origin e destination; zonas de 0 a 8. Use --requests para rodar o simulador com outro arquivo no mesmo formato.','Requests from the commuter scenario, seed 7. Columns: id, minute, origin and destination; zones 0 to 8. Use --requests to run the simulator with another file in the same format.')+bi('a','Baixar demanda CSV','Download demand CSV','class="button ghost" href="demand-sample.csv" download')+'</section>'
    command=f'python {p["package"]}.py --output report.json'
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(p['description'])}"><title>{esc(p['title'])} · Murillo Carvalho</title><link rel="stylesheet" href="../../styles.css"><link rel="stylesheet" href="../../projects.css"><link rel="stylesheet" href="../mobility.css"><script src="../../script.js" defer></script><script src="../mobility-lab.js" type="module"></script></head><body class="project-detail mobility-page" data-mobility="{kind}"><a class="skip-link" href="#content">{esc('Ir ao conteúdo / Skip to content')}</a><header class="topbar"><a class="logo" href="../../#home">Murillo<span>Ed</span></a><nav><a href="../temas/{TOPIC}/">ML e AI Mobility</a></nav><div class="header-tools"><button class="lang-toggle" type="button">EN / PT</button></div></header><main id="content" class="shell"><section class="project-detail-hero"><div><span class="section-index">ML & AI MOBILITY / PYTHON SIMULATION</span>{bi('h1',p['title'],p['title_en'])}{bi('p',p['description'],p['description_en'],'class="project-lead"')}<div class="project-status">{bi('span','MVP executável · dados sintéticos','Executable MVP · synthetic data')}</div><div class="project-tags">{''.join('<span>'+esc(t)+'</span>' for t in p['tags'])}</div><div class="hero-actions">{bi('a','Baixar código Python','Download Python source','class="button primary" href="source.zip" download')}{bi('a','Resultados JSON','JSON results','class="button ghost" href="report.json"')}{bi('a','Ver código no GitHub','View code on GitHub',f'class="button ghost" href="https://github.com/murilloed/murilloed.github.io/tree/main/projects/{slug}/source" target="_blank" rel="noreferrer"')}</div></div><img class="detail-cover" src="../../assets/projects/{slug}.svg" width="640" height="360" alt="{esc(p['title'])}"></section><div class="project-evidence">{evidence}</div>{bi('p','Estudo independente com dados sintéticos. Não representa experiência profissional, entrega a cliente ou desempenho em produção.','Independent study with synthetic data. Not a claim of professional experience, client delivery or production performance.','class="project-provenance"')}<section class="project-panel project-summary">{bi('h2','Resumo do projeto','Project overview')}<div class="summary-grid">{summary}</div></section><section class="project-panel mobility-lab">{bi('span','LABORATÓRIO INTERATIVO / SINTÉTICO','INTERACTIVE LAB / SYNTHETIC','class="mini-label"')}{bi('h2','Explore o simulador','Explore the simulator')}{bi('p','Calcule rotas e tráfego no navegador ou explore execuções Python de frotas. As métricas abaixo pertencem ao cenário selecionado.','Compute routing and traffic in your browser or explore Python fleet runs. The metrics below belong to the selected scenario.')}{controls(p)}<div class="mobility-stage"><svg id="mobility-map" viewBox="0 0 530 460" role="img" aria-label="Synthetic mobility simulation"></svg><div><div id="lab-stats" class="mobility-stats"></div><p id="lab-status" aria-live="polite">Loading…</p></div></div>{playback}<div class="mobility-controls">{bi('button','Exportar execução JSON','Export run JSON','id="download-run" type="button"')}</div></section>{extra}<div class="project-detail-grid"><section class="project-panel">{bi('h2','Reproduza o experimento','Reproduce the experiment')}{bi('p','Extraia source.zip. Requer Python 3.10 ou superior; apenas biblioteca padrão.','Extract source.zip. Requires Python 3.10 or later; standard library only.')}<pre><code>{esc(command)}\npython -m unittest discover -v</code></pre>{bi('p','Abra README.md para conhecer parâmetros, unidades, hipóteses e protocolo de avaliação.','Open README.md for parameters, units, assumptions and evaluation protocol.')}</section><section class="project-panel">{bi('h2','Evolução de pesquisa','Research roadmap')}{bi('p',*p['next'])}{bi('h3','Referências de implementação','Implementation references')}{''.join(f'<p><a href="{esc(url)}" target="_blank" rel="noreferrer">{esc(title)}</a></p>' for title,url in p['references'])}</section></div><section class="project-panel result-panel">{bi('h2','Relatório de execução Python','Python experiment report')}{bi('p','O relatório é gerado pelo código publicado. As animações de frota usam a seed 7; os indicadores agregam três seeds. Não há benchmark com dados reais.','The report is generated by the published code. Fleet animations use seed 7; aggregate metrics use three seeds. There is no real-data benchmark.')}<details>{bi('summary','Inspecionar resultados e limites','Inspect results and limitations')}<pre><code id="report-json">Loading…</code></pre></details></section><a class="button ghost back-projects" href="../temas/{TOPIC}/">ML e AI Mobility</a></main><footer class="site-footer">© <span id="year"></span> Murillo Carvalho</footer></body></html>'''

def card(p,base='../../',asset='../../../'):
    slug=p['slug']
    return f'''<article class="project-card" data-category="{p['category']}"><a class="project-cover" href="{base}{slug}/" aria-label="{esc(p['title'])}"><img src="{asset}assets/projects/{slug}.svg" alt="" loading="lazy" width="640" height="360"></a><div class="project-body"><div class="project-status">{bi('span','MVP executável · sintético','Executable MVP · synthetic')}</div>{bi('h3',p['title'],p['title_en'])}{bi('p',p['description'],p['description_en'],'class="project-description"')}<p class="project-context"><b>Urban mobility · Independent research</b></p><div class="project-tags">{''.join('<span>'+esc(t)+'</span>' for t in p['tags'])}</div><div class="project-actions">{bi('a','Explorar projeto','Explore project',f'href="{base}{slug}/"')}{bi('a','Baixar código','Download source',f'href="{base}{slug}/source.zip" download')}</div></div></article>'''

def cover(p):
    kind=p['kind'];art=''
    if kind=='gps':
        for y in range(5):
            for x in range(7):art+=f'<path d="M {95+x*65} 65 V 280 M 95 {65+y*50} H 485" stroke="#25465d"/>'
        art+='<path d="M95 215 H225 V115 H485 V215" fill="none" stroke="#2de2e6" stroke-width="7" stroke-linejoin="round"/><circle cx="95" cy="215" r="10" fill="#78dfba"/><circle cx="485" cy="215" r="10" fill="#e7b673"/>'
    elif kind=='cars':
        art='<ellipse cx="320" cy="160" rx="215" ry="95" fill="none" stroke="#203f56" stroke-width="34"/><ellipse cx="320" cy="160" rx="215" ry="95" fill="none" stroke="#8294a4" stroke-dasharray="9 9"/>'
        import math
        for i in range(18):
            a=i/18*math.pi*2;art+=f'<circle cx="{320+215*math.cos(a):.1f}" cy="{160+95*math.sin(a):.1f}" r="7" fill="{"#f0b273" if i<4 else "#2de2e6"}"/>'
    else:
        for y in range(3):
            for x in range(3):
                art+=f'<rect x="{145+x*115}" y="{45+y*75}" width="100" height="60" rx="9" fill="#183548" stroke="#396375"/>'
                for i in range(x+y+1):art+=f'<circle cx="{160+x*115+i*17}" cy="{75+y*75}" r="5" fill="{"#e7b673" if i%2 else "#2de2e6"}"/>'
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360" viewBox="0 0 640 360"><rect width="640" height="360" fill="#081b2c"/>{art}<text x="30" y="330" fill="#dbedf6" font-family="system-ui" font-size="20">{esc(p["title"])}</text></svg>'

def main():
    projects=json.loads((ROOT/'projects.json').read_text(encoding='utf-8'))
    for p in PROJECTS:
        d=ROOT/'projects'/p['slug'];d.mkdir(exist_ok=True,parents=True)
        report=d/'report.json'
        if report.exists():report.write_text(json.dumps(json.loads(report.read_text(encoding='utf-8')),separators=(',',':')),encoding='utf-8')
        (d/'index.html').write_text(page(p),encoding='utf-8')
        (ROOT/'assets/projects'/f'{p["slug"]}.svg').write_text(cover(p),encoding='utf-8')
        readme=f'''# {p['title']}\n\n{p['description']}\n\n{p['description_en']}\n\n## Run / Executar\n\nPython 3.10+, standard library only. Extract the archive and run from its directory:\n\n```sh\npython {p['package']}.py --output report.json\npython -m unittest discover -v\n```\n\n## Implementation\n\n{p['implementation'][1]}\n\n## Evaluation\n\n{p['validation'][1]}\n\n## Limitations\n\n{p['limits'][1]}\n\n## Next steps\n\n{p['next'][1]}\n\nIndependent research. All supplied data is synthetic. No client endorsement or real-world performance claim.\n'''
        if p['kind']=='fleet':readme+='\n## Observed data\n\n`python fleetmind.py --observed counts.csv --output validation.json`\n\nCSV header: `minute,observed,simulated`. Unique, nonnegative integer minute keys and finite nonnegative counts. Align units, timezone, intervals and provenance before comparing. MAE/RMSE do not automatically calibrate the simulation. Q-learning trains on seeds 100–123 with fleet size 16. Test policies use the exact same request stream per seed (7/8/9). Demand forecasting uses separate synthetic seeds (30–35 train, 70–72 test). Each zone edge is 0.5 km and one minute; horizon 120 min; waiting requests expire after 12 min. Completed-request rate counts arrivals before the horizon; in-progress requests are reported separately. Shared Q table is an exploratory multi-agent coordination baseline with limited state, not a deployment-ready controller.\n'
        (d/'source/README.md').write_text(readme,encoding='utf-8')
        if p['kind']=='fleet':
            with (d/'source/README.md').open('a',encoding='utf-8') as handle:
                handle.write('\n### Custom scenarios and request data\n\n`python fleetmind.py --single --city commuter --fleet 8 --policy qlearning --seed 7 --export-demand demand.csv --output run.json`\n\n`python fleetmind.py --requests requests.csv --fleet 16 --policy nearest --output observed-input-run.json`\n\nRequest CSV columns: `minute,origin,destination` (zones 0..8; origin differs from destination). Requests at minute 120 or later fall outside the current evaluation horizon. Imported data is labeled user supplied, with unverified provenance. The sample downloadable demand dataset is synthetic.\n')
        (d/'source/LICENSE').write_text('MIT License\n\nCopyright (c) 2026 Murillo Edson de Carvalho Souza\n\nPermission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\n',encoding='utf-8')
        with zipfile.ZipFile(d/'source.zip','w',zipfile.ZIP_DEFLATED) as z:
            for f in sorted((d/'source').iterdir()):
                if f.is_file():z.write(f,f.name)
        if not any(x['slug']==p['slug'] for x in projects):projects.append({k:p[k] for k in ('slug','title','title_en','category','context','description','description_en','tags','package','themes')})
    (ROOT/'projects.json').write_text(json.dumps(projects,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    link='<a href="../ml-ai-mobility/" data-pt="ML e AI Mobility" data-en="ML & AI Mobility">ML e AI Mobility</a>'
    for f in (ROOT/'projects/temas').glob('*/index.html'):
        s=f.read_text(encoding='utf-8')
        if f.parent.name==TOPIC:continue
        if 'href="../ml-ai-mobility/"' not in s:s=s.replace('<div class="topic-navigation">','<div class="topic-navigation">'+link)
        if f.parent.name=='todos':
            for p in PROJECTS:
                if f'href="../../{p["slug"]}/"' not in s:s=s.replace('</div></main>',card(p)+'</div></main>')
            s=re.sub(r'data-pt="\d+ projetos" data-en="\d+ projects">\d+ projetos',f'data-pt="{len(projects)} projetos" data-en="{len(projects)} projects">{len(projects)} projetos',s)
        f.write_text(s,encoding='utf-8')
    template=(ROOT/'projects/temas/reforco/index.html').read_text(encoding='utf-8')
    nav=re.search(r'<div class="topic-navigation">.*?</div>',template).group()
    nav=re.sub(r' aria-current="page"','',nav).replace('href="../ml-ai-mobility/"','href="../ml-ai-mobility/" aria-current="page"')
    folder=ROOT/'projects/temas'/TOPIC;folder.mkdir(exist_ok=True)
